stocks=[]
for r in rows:
    t=r.get("ticker",""); desc=info.get(t,[f"{names.get(t,t)} participates in the broader AI technology ecosystem.","Its products or services have exposure to AI-related demand.","Like any stock, price and business performance can change."])
    stocks.append({"rank":r.get("rank",0),"ticker":t,"name":names.get(t,t),"score":round(float(r.get("score",0) or 0),1),"price":round(float(r.get("price",0) or 0),2),"risk":r.get("risk","—"),"what":desc[0],"why":desc[1],"riskText":desc[2]})

