html=f'''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no"><style>
*{{box-sizing:border-box}}html,body{{margin:0;background:#020711;color:#f2f8ff;font-family:Arial,Helvetica,sans-serif}}body{{padding:6px 3px 90px}}.app{{max-width:920px;margin:auto}}.cyan{{color:#22d3ee}}.pink{{color:#e879f9}}.green{{color:#4ade80}}.orange{{color:#fb923c}}.muted{{color:#94a9c1;font-size:13px}}.panel{{border:1px solid #17365f;border-radius:22px;padding:15px;margin:10px 0;background:linear-gradient(180deg,#081322,#030812)}}.plan{{background:radial-gradient(circle at 10% 15%,#ec489944,transparent 26%),radial-gradient(circle at 90% 5%,#0ea5e940,transparent 28%),linear-gradient(120deg,#24104d,#07345b,#481c08);border-color:#a855f7}}h2{{margin:0 0 4px;font-size:23px}}.steps{{display:flex;gap:6px;flex-wrap:wrap;margin:9px 0}}.step{{background:#0b1a2b;border:1px solid #244e80;border-radius:999px;padding:6px 9px;font-size:11px;font-weight:900}}.mode{{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:12px 0}}button{{border:1px solid #275078;border-radius:13px;background:#07111f;color:white;padding:12px;font-weight:900;cursor:pointer}}button.active,button.primary{{background:linear-gradient(90deg,#0ea5e9,#7c3aed);border-color:#22d3ee;box-shadow:0 0 14px #22d3ee35}}label{{display:block;font-size:11px;font-weight:900;color:#b7c9dd;margin:10px 0 5px}}select,input{{width:100%;background:#06101d;border:1px solid #315177;color:white;border-radius:13px;padding:12px;font-size:16px}}.quick{{display:grid;grid-template-columns:repeat(5,1fr);gap:6px}}.two{{display:grid;grid-template-columns:1fr 1fr;gap:9px}}.selected{{background:#052d23;border:1px solid #22c55e;border-radius:14px;padding:11px;margin:8px 0;font-weight:900}}.rotation{{display:none;margin-top:8px;padding:11px;border:1px solid #7c3aed;border-radius:15px;background:#130b2d}}.rotation.show{{display:block}}.route{{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px}}.pill{{padding:7px 9px;border-radius:999px;background:#0a2338;border:1px solid #22d3ee;color:#b8efff;font-size:12px;font-weight:900}}.scenario{{margin-top:9px;border-top:1px solid #244e80;padding-top:8px}}.scenarioBody{{display:none}}.scenarioBody.show{{display:block}}.stocks{{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-top:10px}}.stock{{display:grid;grid-template-columns:42px 1fr auto;gap:9px;align-items:center;text-align:left;background:#07111f;border:1px solid #17365f;border-radius:15px;padding:11px;color:white}}.stock.active{{border-color:#22d3ee;background:#09253b}}.badge{{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;border:2px solid #22c55e;color:#4ade80;font-weight:900}}.stockName{{font-weight:900}}.ticker{{font-size:11px;color:#91a7c0}}.price{{font-weight:900}}.stockActions{{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;gap:6px}}.info{{display:none;grid-column:1/-1;background:linear-gradient(120deg,#0b1630,#15103a);border:1px solid #7c3aed;border-radius:13px;padding:11px}}.info.show{{display:block}}.info b{{color:#22d3ee}}.info .risk{{color:#fbbf24}}.results{{display:none}}.results.show{{display:block}}.cards{{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}}.card,.breakdown,.upcoming{{background:#07111f;border:1px solid #17365f;border-radius:14px;padding:11px}}.card small{{display:block;color:#8fa6bf;font-size:9px}}.card strong{{font-size:18px}}.breakrow,.deposit{{display:flex;justify-content:space-between;gap:8px;padding:7px 0;border-bottom:1px solid #14263a;font-size:13px}}.learn{{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}}.learn div{{border-radius:15px;padding:12px;min-height:105px;background:#07111f;border:1px solid #17365f}}.ref{{border:1px solid #22c55e;background:linear-gradient(120deg,#052e16,#07182c);border-radius:18px;padding:14px;margin-top:10px}}.ref a{{display:block;text-align:center;text-decoration:none;background:#22c55e;color:#03210f;font-weight:1000;border-radius:13px;padding:13px;margin-top:9px}}.nav{{position:fixed;bottom:8px;left:50%;transform:translateX(-50%);width:min(94%,780px);display:flex;justify-content:space-around;background:#07111ff4;border:1px solid #17365f;border-radius:18px;padding:9px;z-index:99;box-shadow:0 0 30px #000}}.nav a{{color:#9fb6d3;text-decoration:none;font-size:10px;font-weight:900;text-align:center}}.nav span{{display:block;color:#22d3ee;font-size:18px}}@media(max-width:650px){{.stocks{{grid-template-columns:1fr}}.cards{{grid-template-columns:repeat(2,1fr)}}.learn{{grid-template-columns:repeat(2,1fr)}}}}
</style></head><body><div class="app" id="home"><section class="panel plan" id="sim"><h2>🎯 BUILD YOUR PAYDAY PLAN</h2><div class="muted">Three easy steps. No finance experience needed.</div><div class="steps"><span class="step">1 PICK STOCK(S)</span><span class="step">2 PICK $ AMOUNT</span><span class="step">3 PICK DATES</span></div><div class="mode"><button id="oneBtn" class="active" onclick="setMode('one')">ONE STOCK</button><button id="rotBtn" onclick="setMode('rotation')">ROTATION MODE</button></div><div id="selected" class="selected"></div><div id="rotation" class="rotation"><b class="pink">YOUR ROTATION</b><div class="muted">Add 2–5 stocks in the order you want to buy them each payday.</div><div class="two"><select id="rotSelect"></select><button onclick="addRotation()">+ ADD STOCK</button></div><div id="route" class="route"></div><button style="margin-top:7px" onclick="clearRotation()">CLEAR</button></div><label>AMOUNT EACH PAYDAY</label><div class="quick">{''.join(f'<button onclick="setAmt({a})">${a}</button>' for a in [5,10,25,50,100])}</div><input id="amount" type="number" min="1" value="10"><div class="two"><div><label>HOW OFTEN?</label><select id="freq"><option value="14">Every 2 Weeks</option><option value="7">Every Friday</option><option value="30">Monthly</option></select></div><div><label>START</label><input id="start" type="date"></div></div><label>PROJECT THROUGH</label><input id="end" type="date" value="2026-12-31"><div class="scenario"><button onclick="toggleScenario()" style="width:100%">OPTIONAL: SHOW GROWTH SCENARIOS ▾</button><div id="scenarioBody" class="scenarioBody"><label>ILLUSTRATIVE ANNUAL GROWTH</label><select id="growth"><option value="0">No Growth</option><option value="0.05">Moderate 5%</option><option value="0.10">Growth 10%</option></select><div class="muted">Illustration only — not a forecast for any stock.</div></div></div><button class="primary" style="width:100%;margin-top:12px" onclick="calculate()">⚡ SHOW ME HOW THIS ADDS UP</button></section><section class="panel" id="top20"><h2>🔥 TOP 20 AI STOCKS</h2><div class="muted">Tap <b>WHAT IS THIS?</b> for a plain-English company explanation, or USE STOCK to load it into your plan.</div><div class="stocks" id="stocks"></div></section><section id="results" class="panel results"><h2 id="resultTitle">YOUR PLAN</h2><div class="cards"><div class="card"><small>YOU PUT IN</small><strong class="green" id="contrib">$0</strong></div><div class="card"><small>PAYDAYS INVESTED</small><strong class="pink" id="deposits">0</strong></div><div class="card"><small>ILLUSTRATIVE VALUE</small><strong class="cyan" id="value">$0</strong></div><div class="card"><small>STOCKS IN PLAN</small><strong class="orange" id="stockCount">0</strong></div></div><h3>YOUR STOCKS</h3><div id="breakdown" class="breakdown"></div><h3>NEXT PAYCHECKS</h3><div id="upcoming" class="upcoming"></div><div class="muted" style="margin-top:9px">Future prices will change. Growth scenarios are educational illustrations, not predictions or guarantees.</div></section><section class="panel" id="learn"><h2>🎓 START SMALL. LEARN AS YOU GO.</h2><div class="learn"><div><b class="pink">🚀 START SMALL</b><br>$5 or $10 is enough to learn the habit.</div><div><b class="cyan">🧠 TAP TO LEARN</b><br>Every stock has a plain-English explanation.</div><div><b class="green">🎯 BUILD A ROUTINE</b><br>Use one stock or rotate several each payday.</div><div><b class="orange">🛡️ RISK FIRST</b><br>Stocks can fall. This app teaches planning, not guarantees.</div></div></section><div class="ref"><b class="green">🌱 ROBINHOOD REFERRAL</b><br><span class="muted">Optional brokerage link. It never changes rankings or results.</span><a href="https://join.robinhood.com/steveng-15bac4" target="_blank">OPEN ROBINHOOD →</a></div></div><div class="nav"><a href="#home"><span>⌂</span>HOME</a><a href="#sim"><span>🧮</span>PLAN</a><a href="#top20"><span>🔥</span>TOP 20</a><a href="#learn"><span>🎓</span>LEARN</a></div><script>
const stocks={stocks_json};let selected=stocks.find(x=>x.ticker==='NVDA')||stocks[0];let mode='one';let rotation=[];const fmt=n=>'$'+Number(n||0).toLocaleString(undefined,{{minimumFractionDigits:2,maximumFractionDigits:2}});function renderStocks(){{document.getElementById('stocks').innerHTML=stocks.map(s=>`<div class="stock ${{selected&&selected.ticker===s.ticker?'active':''}}"><span class="badge">${{s.rank}}</span><span><span class="stockName">${{s.name}}</span><br><span class="ticker">${{s.ticker}} • Score ${{s.score}} • ${{s.risk}} risk</span></span><span class="price">${{fmt(s.price)}}</span><div class="stockActions"><button onclick="pick('${{s.ticker}}')">USE STOCK</button><button onclick="toggleInfo('${{s.ticker}}')">WHAT IS THIS?</button></div><div id="info-${{s.ticker}}" class="info"><b>WHAT THEY DO</b><br>${{s.what}}<br><br><b>WHY AI CARES</b><br>${{s.why}}<br><br><b class="risk">KEY RISK</b><br>${{s.riskText}}</div></div>`).join('')}}function toggleInfo(t){{document.getElementById('info-'+t).classList.toggle('show')}}function pick(t){{selected=stocks.find(s=>s.ticker===t);document.getElementById('selected').innerHTML=`Selected: <span class="cyan">${{selected.name}} (${{selected.ticker}})</span> • ${{fmt(selected.price)}}`;renderStocks();document.getElementById('sim').scrollIntoView({{behavior:'smooth'}})}}function setMode(m){{mode=m;document.getElementById('oneBtn').classList.toggle('active',m==='one');document.getElementById('rotBtn').classList.toggle('active',m==='rotation');document.getElementById('rotation').classList.toggle('show',m==='rotation')}}function setAmt(a){{document.getElementById('amount').value=a}}function addRotation(){{if(rotation.length>=5)return;let t=document.getElementById('rotSelect').value,s=stocks.find(x=>x.ticker===t);if(s)rotation.push(s);renderRoute()}}function clearRotation(){{rotation=[];renderRoute()}}function renderRoute(){{document.getElementById('route').innerHTML=rotation.map((s,i)=>`<span class="pill">${{i+1}}. ${{s.ticker}}</span>`).join('')}}function toggleScenario(){{document.getElementById('scenarioBody').classList.toggle('show')}}function calculate(){{let amt=Number(document.getElementById('amount').value),days=Number(document.getElementById('freq').value),start=new Date(document.getElementById('start').value+'T12:00:00'),end=new Date(document.getElementById('end').value+'T12:00:00'),rate=Number(document.getElementById('growth').value),plan=mode==='rotation'?rotation:[selected];if(!amt||!plan.length||isNaN(start)||isNaN(end)||end<start){{alert('Choose your stock plan, amount, start date and end date.');return}}if(mode==='rotation'&&rotation.length<2){{alert('Add at least two stocks for Rotation Mode.');return}}let dates=[];for(let d=new Date(start);d<=end;d.setDate(d.getDate()+days))dates.push(new Date(d));let by={{}},futureTotal=0;dates.forEach((d,i)=>{{let s=plan[i%plan.length];if(!by[s.ticker])by[s.ticker]={{s,contrib:0,shares:0,count:0,future:0}};let years=Math.max(0,(end-d)/31557600000),fv=amt*Math.pow(1+rate,years);by[s.ticker].contrib+=amt;by[s.ticker].shares+=amt/s.price;by[s.ticker].count++;by[s.ticker].future+=fv;futureTotal+=fv}});let total=dates.length*amt;document.getElementById('contrib').textContent=fmt(total);document.getElementById('deposits').textContent=dates.length;document.getElementById('value').textContent=fmt(futureTotal);document.getElementById('stockCount').textContent=Object.keys(by).length;document.getElementById('resultTitle').textContent=mode==='rotation'?'YOUR PAYCHECK ROTATION':'YOUR '+selected.ticker+' PLAN';document.getElementById('breakdown').innerHTML=Object.values(by).map(x=>`<div class="breakrow"><span><b>${{x.s.ticker}}</b> • ${{x.contrib.toFixed(0)}} invested</span><span>${{x.count}} buys • ${{x.shares.toFixed(4)}} shares</span></div>`).join('');document.getElementById('upcoming').innerHTML=dates.slice(0,10).map((d,i)=>{{let s=plan[i%plan.length];return `<div class="deposit"><span>${{d.toLocaleDateString()}}</span><span><b>${{s.ticker}}</b> • ${{fmt(amt)}}</span></div>`}}).join('');document.getElementById('results').classList.add('show');document.getElementById('results').scrollIntoView({{behavior:'smooth'}})}}document.getElementById('rotSelect').innerHTML=stocks.map(s=>`<option value="${{s.ticker}}">${{s.name}} (${{s.ticker}})</option>`).join('');let now=new Date();document.getElementById('start').value=now.toISOString().slice(0,10);pick(selected.ticker);renderStocks();
</script></body></html>'''
components.html(html,height=6200,scrolling=False)
